package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.*;
import org.apache.commons.math3.special.Gamma;

/** Explicit zero-intercept regression; centered R-squared is never substituted for its baseline. */
public final class OriginRegression {
    private OriginRegression(){}
    public record Fit(int observations,int predictors,int residualDegreesOfFreedom,RobustRegression.Covariance covariance,double confidence,
                      double[] coefficients,double[][] coefficientCovariance,List<Inference.Term> terms,double residualSumOfSquares,
                      double uncenteredRSquared,double adjustedUncenteredRSquared,double modelStatistic,double modelPValue,String modelReference,
                      double[] fitted,double[] residuals,double[] leverage,double[] studentizedResiduals,double[] cooksDistance,List<String> warnings){
        public Fit{coefficients=coefficients.clone();coefficientCovariance=Matrices.copy(coefficientCovariance);terms=List.copyOf(terms);fitted=fitted.clone();residuals=residuals.clone();leverage=leverage.clone();studentizedResiduals=studentizedResiduals.clone();cooksDistance=cooksDistance.clone();warnings=List.copyOf(warnings);}
        @Override public double[] coefficients(){return coefficients.clone();}@Override public double[][] coefficientCovariance(){return Matrices.copy(coefficientCovariance);}@Override public double[] fitted(){return fitted.clone();}@Override public double[] residuals(){return residuals.clone();}@Override public double[] leverage(){return leverage.clone();}@Override public double[] studentizedResiduals(){return studentizedResiduals.clone();}@Override public double[] cooksDistance(){return cooksDistance.clone();}
        public double predict(double[] row){if(row.length!=coefficients.length)throw new IllegalArgumentException("Origin-regression predictor count differs.");double value=0;for(int i=0;i<row.length;i++){if(!Double.isFinite(row[i]))throw new IllegalArgumentException("Forecast predictors must be finite.");value=Math.fma(row[i],coefficients[i],value);}if(!Double.isFinite(value))throw new IllegalArgumentException("Forecast exceeded numeric range.");return value;}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    public static Fit fit(double[][] predictors,double[] response,RobustRegression.Covariance covariance,double confidence){
        Matrices.interrupted();Objects.requireNonNull(covariance);Inference.confidence(confidence);int p=Matrices.width(predictors,2),n=predictors.length;if(p<1||p>512||response.length!=n||n<=p||(long)n*p>5_000_000)throw new IllegalArgumentException("Origin regression needs 1–512 predictors, positive residual df and at most five million design cells.");double[][] scaled=Matrices.copy(predictors);double[] scales=new double[p];for(int j=0;j<p;j++){for(var row:predictors)scales[j]=Math.max(scales[j],Math.abs(row[j]));if(!(scales[j]>0))throw new IllegalArgumentException("A zero predictor cannot identify an origin-regression slope.");for(int i=0;i<n;i++)scaled[i][j]/=scales[j];}for(double value:response)if(!Double.isFinite(value))throw new IllegalArgumentException("Response must be finite.");RealMatrix x=new Array2DRowRealMatrix(scaled,false);var qr=new QRDecomposition(x,1e-12);if(!qr.getSolver().isNonSingular())throw new IllegalArgumentException("Origin-regression predictors are rank deficient.");double[] normalized=qr.getSolver().solve(new ArrayRealVector(response,false)).toArray(),beta=normalized.clone();for(int j=0;j<p;j++){beta[j]/=scales[j];if(!Double.isFinite(beta[j]))throw new IllegalArgumentException("Origin-regression coefficient exceeded numeric range.");}RealMatrix r=qr.getR().getSubMatrix(0,p-1,0,p-1),rInverse=new LUDecomposition(r,1e-14).getSolver().getInverse(),bread=rInverse.multiply(rInverse.transpose());
        double[] fitted=new double[n],residuals=new double[n],leverage=new double[n],studentized=new double[n],cooks=new double[n];double rss=0,tss=0;for(int i=0;i<n;i++){Matrices.interrupted();for(int j=0;j<p;j++)fitted[i]=Math.fma(scaled[i][j],normalized[j],fitted[i]);residuals[i]=response[i]-fitted[i];rss+=residuals[i]*residuals[i];tss+=response[i]*response[i];double h=0;for(int a=0;a<p;a++)for(int b=0;b<p;b++)h+=scaled[i][a]*bread.getEntry(a,b)*scaled[i][b];leverage[i]=Math.max(0,Math.min(1,h));if(1-leverage[i]<=1e-12&&(covariance==RobustRegression.Covariance.HC2||covariance==RobustRegression.Covariance.HC3||covariance==RobustRegression.Covariance.HC4))throw new IllegalArgumentException(covariance+" is undefined for a unit-leverage origin-regression row.");}if(!Double.isFinite(rss)||!Double.isFinite(tss))throw new IllegalArgumentException("Origin-regression sums of squares exceeded numeric range; rescale the response.");int df=n-p;double mse=rss/df;for(int i=0;i<n;i++){double remaining=1-leverage[i];studentized[i]=mse>0&&remaining>1e-12?residuals[i]/Math.sqrt(mse*remaining):Double.NaN;cooks[i]=mse>0&&remaining>1e-12?residuals[i]*residuals[i]*leverage[i]/(p*mse*remaining*remaining):Double.NaN;}
        RealMatrix estimate;if(covariance==RobustRegression.Covariance.CLASSICAL)estimate=bread.scalarMultiply(mse);else{double[][] meat=new double[p][p];for(int i=0;i<n;i++){double value=residuals[i]*residuals[i];if(covariance==RobustRegression.Covariance.HC1)value*=n/(double)df;else if(covariance==RobustRegression.Covariance.HC2)value/=1-leverage[i];else if(covariance==RobustRegression.Covariance.HC3)value/=Math.pow(1-leverage[i],2);else if(covariance==RobustRegression.Covariance.HC4)value/=Math.pow(1-leverage[i],Math.min(4,n*leverage[i]/p));for(int a=0;a<p;a++)for(int b=0;b<p;b++)meat[a][b]+=scaled[i][a]*scaled[i][b]*value;}estimate=bread.multiply(new Array2DRowRealMatrix(meat,false)).multiply(bread);}
        double[][] original=estimate.getData();for(int a=0;a<p;a++)for(int b=0;b<p;b++){original[a][b]/=scales[a];original[a][b]/=scales[b];if(!Double.isFinite(original[a][b]))throw new IllegalArgumentException("Origin-regression covariance exceeded numeric range.");}List<Inference.Term> terms=new ArrayList<>();TDistribution student=new TDistribution(df);NormalDistribution normal=new NormalDistribution();boolean classical=covariance==RobustRegression.Covariance.CLASSICAL;double critical=classical?student.inverseCumulativeProbability((1+confidence)/2):normal.inverseCumulativeProbability((1+confidence)/2);for(int j=0;j<p;j++){double variance=original[j][j];if(variance< -1e-10)throw new IllegalArgumentException("Invalid origin-regression covariance.");double se=Math.sqrt(Math.max(0,variance)),ratio=Inference.ratio(beta[j],se),probability=Double.isFinite(ratio)?classical?2*student.cumulativeProbability(-Math.abs(ratio)):Inference.normalTwoSided(ratio):Double.NaN;terms.add(new Inference.Term(beta[j],se,ratio,probability,beta[j]-critical*se,beta[j]+critical*se));}
        double rSquared=tss>0?1-rss/tss:Double.NaN,adjusted=Double.isFinite(rSquared)?1-(1-rSquared)*n/df:Double.NaN,statistic=Double.NaN,probability=Double.NaN;String reference;List<String>warnings=new ArrayList<>();if(classical){reference="Classical F test of all slopes zero against the zero-response baseline";if(mse>0&&tss>0){statistic=Math.max(0,(tss-rss)/p/mse);probability=org.apache.commons.math3.special.Beta.regularizedBeta(df/(df+p*statistic),df/2.0,p/2.0);}}else{reference="Asymptotic chi-square Wald test of all slopes zero";var decomposition=new SingularValueDecomposition(estimate);if(decomposition.getRank()==p){RealVector b=new ArrayRealVector(normalized,false);statistic=Math.max(0,b.dotProduct(decomposition.getSolver().solve(b)));probability=Gamma.regularizedGammaQ(p/2.0,statistic/2);}else warnings.add("Robust coefficient covariance is singular; the joint Wald test is unavailable.");warnings.add("HC covariance uses asymptotic normal coefficient inference and an asymptotic chi-square joint test; it does not supply clustered or serially robust inference.");}
        warnings.add("The intercept is fixed at zero by model specification. R-squared and adjusted R-squared use the uncentered sum of squared responses and cannot be directly compared with centered intercept-model R-squared.");if(tss==0)warnings.add("The response has zero uncentered variation; uncentered R-squared and the classical model test are unavailable.");if(mse==0)warnings.add("Zero empirical residual variance does not establish sampling certainty; ratio/influence diagnostics can be unavailable.");return new Fit(n,p,df,covariance,confidence,beta,original,terms,rss,rSquared,adjusted,statistic,probability,reference,fitted,residuals,leverage,studentized,cooks,warnings);
    }
    public static Resampled bootstrap(double[][] predictors,double[] response,RobustRegression.Covariance covariance,double confidence,Bootstrap.Options options,IntConsumer progress){Fit point=fit(predictors,response,covariance,confidence);int p=point.predictors();double[][] combined=new double[predictors.length][p+1];for(int i=0;i<combined.length;i++){System.arraycopy(predictors[i],0,combined[i],0,p);combined[i][p]=response[i];}List<Bootstrap.Parameter> parameters=new ArrayList<>();for(int j=0;j<p;j++)parameters.add(new Bootstrap.Parameter("Origin-regression slope",-1,-1,j,"Predictor "+(j+1)));var inference=Resampling.run(combined,parameters,point.coefficients(),options,(sample,rows)->{double[][] x=new double[sample.length][p];double[] y=new double[sample.length];for(int i=0;i<sample.length;i++){System.arraycopy(sample[i],0,x[i],0,p);y[i]=sample[i][p];}return fit(x,y,covariance,confidence).coefficients();},progress,"Regression through the origin","Each iid case/jackknife draw refits the constrained zero-intercept design; no artificial intercept or duplicated observations are introduced.");return new Resampled(point,inference);}
}
